package com.bananalab.lite;
import android.content.Context;import java.util.*;
/** Optional public references: data retrieval, never a model-training service. */
final class BananaReferences{
 static final String SOURCES="Investigación: buscador web DuckDuckGo HTML (puede cambiar o bloquearse); alternativa Wikipedia ES. Páginas públicas HTTPS, fuentes y fecha de consulta. Biblioteca separada de los pesos del modelo.\n\nReferencias visuales opcionales:\niNaturalist · animales y plantas\nNASA · espacio y Tierra\nCleveland Museum of Art · arte y objetos\nMetropolitan Museum of Art · arte y escenas\nWikipedia ES/EN · descripciones\nWikimedia Commons · referencias adicionales\n\nCada referencia conserva origen y créditos. La disponibilidad depende de Internet y de cada fuente.";
 static String fetch(Context c,SceneDraft snapshot)throws Exception{Set<String> topics=new LinkedHashSet<>();for(SceneDraft.Actor a:snapshot.cast)if(topics.size()<3)topics.add(a.kind);if(topics.isEmpty())topics.add(snapshot.setting);StringBuilder result=new StringBuilder("Referencias del resultado:");for(String topic:topics){if(Thread.currentThread().isInterrupted())throw new java.io.IOException("Consulta cancelada");try{result.append("\n").append(WebMemory.lookup(c,topic));}catch(Exception e){result.append("\nNo pude consultar ").append(topic).append(". Se conserva la memoria anterior.");}if(Thread.currentThread().isInterrupted())throw new java.io.IOException("Consulta cancelada");try{VisualMemory.fetch(c,topic);}catch(Exception ignored){}}return result.append("\nPodés ver los textos y las imágenes guardadas desde Proyecto.").toString();}
}
